import Swift

// a bounded async channel with explicit backpressure and a close:
actor AsyncQueue<Element> {
    private var storage: [Element] = []
    private var waiters: [(Element) -> Void] = []
    private var finished = false
    private let capacity: Int

    init(capacity: Int) { self.capacity = capacity }

    func put(_ element: Element) async throws {
        if finished { throw CancellationError() }            // send-after-close
        if storage.count < capacity { storage.append(element); return }
        await withCheckedContinuation { waiters.append($0) }   // FULL: suspend (backpressure)
    }
    func finish() { finished = true }                        // the producer closes
}

// Structured concurrency has absorbed many channel uses:
await withTaskGroup(of: Void.self) { group in
    for id in ids { group.addTask { await handle(id) } }    // concurrent, bounded by the group
}
